@php $shift=\Illuminate\Support\Facades\Schema::hasTable('su_shifts')?\Illuminate\Support\Facades\DB::table('su_shifts')->where('is_closed',false)->latest('id')->first():null;$moves=$records; $incoming=$moves->where('direction','in')->sum('amount');$outgoing=$moves->where('direction','out')->sum('amount');$opening=(float)($shift->opening_cash??0)+(float)($shift->opening_mobile_money??0); @endphp
<div class="sw-shift-card"><div class="sw-shift-header"><div><h3>{{ $shift?'Shift open':'No open shift' }}</h3><small>{{ $shift?'Shift #'.$shift->id.' • Opened '.$shift->opened_at:'Open a shift to begin recording cash activity' }}</small></div><span class="sw-pill">{{ $shift?'Shift active':'Shift closed' }}</span></div><small>TOTAL ON HAND</small><div class="sw-big-money">{{ number_format($opening+$incoming-$outgoing,0) }}</div><p>Expected balance = opening float + money received − money paid out</p><div class="sw-shift-buttons"><button disabled>＋ Money in</button><button disabled>－ Money out</button><a href="{{ route('manage.workspace.cashbox',['page'=>'reports']) }}">▥ View reports</a></div><small class="sw-note">Cash movement entry will be enabled after reconciliation services are connected.</small></div>
<div class="sw-cash-metrics">@foreach([['CASH ON HAND',$shift->opening_cash??0],['MPESA ON HAND',$shift->opening_mobile_money??0],['MONEY IN',$incoming],['MONEY OUT',$outgoing],['OPENING FLOAT',$opening],['NET MOVEMENT',$incoming-$outgoing]] as $metric)<div class="sw-metric"><small>{{ $metric[0] }}</small><strong>{{ number_format((float)$metric[1],0) }}</strong><p>Current shift</p></div>@endforeach</div><div class="sw-chart-card"><h3>Recent activity</h3><small>Latest 20 entries</small>@forelse($moves->take(20) as $movement)<div class="sw-person-row"><i class="fa-solid fa-arrow-{{ $movement->direction==='in'?'down':'up' }}"></i><div><strong>{{ $movement->type??'Cash movement' }}</strong><small>{{ $movement->created_at??'' }}</small></div><span>{{ number_format((float)$movement->amount,0) }}</span></div>@empty<div class="sw-empty">No recent activity.</div>@endforelse</div>
